// ============================================
// VALIDATE CALLBACK INPUT
// ============================================

const input = $input.first().json;
const body = input.body || input;

// --- Required fields ---
const jobId = body.job_id;
const userId = body.user_id;
const guildId = body.guild_id;
const channelId = body.channel_id;
const success = body.success;

const errors = [];
if (!jobId) errors.push('job_id');
if (!userId) errors.push('user_id');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    message: 'Missing required fields: ' + errors.join(', ')
  };
}

// --- Extract result data ---
const result = body.result || {};
const metrics = body.metrics || {};
const error = body.error || null;

return {
  valid: true,
  data: {
    job_id: jobId,
    user_id: userId,
    guild_id: guildId,
    channel_id: channelId,
    conversation_id: body.conversation_id,
    success: success === true,
    result: {
      text: result.text || '',
      output_type: result.output_type || 'text',
      word_count: result.word_count || 0
    },
    metrics: {
      tokens_used: metrics.tokens_used || 0,
      processing_time_ms: metrics.processing_time_ms || 0,
      ocr_confidence: metrics.ocr_confidence || 0,
      pages_processed: metrics.pages_processed || 0
    },
    error: error
  }
};

// ============================================
// PREPARE DISCORD NOTIFICATION
// ============================================

const data = $('Validate Input').first().json.data;
const jobUpdateResult = $input.first().json;

// --- Build notification message ---
let message;
if (data.success) {
  const text = data.result.text;
  const truncated = text.length > 1500 ? text.substring(0, 1500) + '...' : text;
  const processingTime = (data.metrics.processing_time_ms / 1000).toFixed(1);

  message = `**Document traité avec succès**\n\n` +
    `**Résultat:**\n${truncated}\n\n` +
    `**Statistiques:**\n` +
    `- Mots: ${data.result.word_count}\n` +
    `- Temps: ${processingTime}s\n` +
    `- Pages: ${data.metrics.pages_processed}`;
} else {
  const errorCode = data.error?.code || 'UNKNOWN_ERROR';
  const errorMessage = data.error?.message || 'Une erreur est survenue';
  const retriable = data.error?.retriable ? 'Oui' : 'Non';

  message = `**Erreur de traitement**\n\n` +
    `**Code:** ${errorCode}\n` +
    `**Message:** ${errorMessage}\n` +
    `**Réessayable:** ${retriable}`;

  if (data.error?.refund?.recommended) {
    message += `\n**Remboursement:** ${data.error.refund.percentage}% recommandé`;
  }
}

return {
  channel_id: data.channel_id,
  user_id: data.user_id,
  guild_id: data.guild_id,
  message: message,
  success: data.success,
  job_id: data.job_id
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const discordResult = $input.first().json;
const msgData = $('Prepare Discord Message').first().json;

return {
  success: true,
  job_id: msgData.job_id,
  notification_sent: discordResult.id ? true : false,
  message: 'Callback processed successfully'
};

// ============================================
// FORMAT NO CHANNEL RESPONSE
// ============================================

const msgData = $input.first().json;

return {
  success: true,
  job_id: msgData.job_id,
  notification_sent: false,
  message: 'Callback processed (no channel to notify)'
};

// ============================================
// FORMAT VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.message || 'Invalid callback data',
    http_status: 400
  }
};

